from mixroom.tracks.store import Crate
from mixroom.tracks.models import Track
def mk(n, cat='x'):
    s = Crate()
    for k in range(n):
        s.add(Track(id='k%02d' % k, title='N%02d' % k, mood=cat, plays=(k * 5) % 7, price=1.0 + k))
    return s
from mixroom.tracks.errors import Invalid
s = mk(2)
try:
    s.add(Track(id='k01', title='z', mood='c'))
except Invalid as e:
    print(e, s.count(), s.get('k01').title)

